//! ✉️ Canonical history envelopes move actual admitted payloads and bound original header fragments.
use semio_framework_os_spr::{ActorId,ArtifactId,SchemaId,MutationId,MutationEnvelope,ArtifactDiff,InverseMutation,CausalPayload,HybridLogicalTimestamp,HISTORY_TRANSITION_SCHEMA};
use semio_framework_value::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneClose,retained_clone_grant_admits}};
use std::mem::{ManuallyDrop,size_of};
/// 🪡️ This pure codec reborrows text whose enclosing original publisher retains its genuine source fence.
pub struct OriginalHistoryEnvelopeHeader{actor:ManuallyDrop<Option<ActorId>>,text:ManuallyDrop<[Option<String>;5]>,retirement:RetainedCloneClose,source:Option<[(usize,usize);3]>,field:usize,taken:bool,closing:bool}
impl Default for OriginalHistoryEnvelopeHeader{fn default()->Self{Self{actor:ManuallyDrop::new(None),text:ManuallyDrop::new([None,None,None,None,None]),retirement:Default::default(),source:None,field:0,taken:false,closing:false}}}
fn invalid(text:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,text)}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn progress(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
fn stamp(document:&str,actor:&ActorId,observed:Option<&str>)->[(usize,usize);3]{[(document.as_ptr()as usize,document.len()),(actor.0.as_ptr()as usize,actor.0.len()),observed.map_or((0,0),|text|(text.as_ptr()as usize,text.len()))]}
impl OriginalHistoryEnvelopeHeader{
 /// 📏️ Quotes one header reservation, bounded UTF8 body fragment or completed field handoff.
 pub fn demands(&self,document:&str,actor:&ActorId,observed:Option<&str>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return self.close_demands(body)}if self.source.is_some_and(|source|source!=stamp(document,actor,observed)){return Err(invalid("history envelope header changed its original text sources"))}if self.ready(){return Ok(Default::default())}if self.field==1{return Ok(header::<ActorId>())}let source=match self.field{0=>Some(document),1=>None,2|3=>Some(HISTORY_TRANSITION_SCHEMA),4=>observed,_=>return Ok(Default::default())};let Some(source)=source else{return Ok(header::<usize>())};let Some(target)=self.text[self.field].as_ref()else{return Ok(RetirementDemand{capacity_bytes:source.len(),..header::<Option<String>>()})};if target.len()==source.len(){return Ok(header::<usize>())}Ok(RetirementDemand{copy_bytes:64+2*size_of::<usize>(),depth:1,..Default::default()})}
 /// 🧵️ Copies at most one source fragment after its exact independent reservation is funded.
 pub fn advance(&mut self,document:&str,actor:&ActorId,observed:Option<&str>,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{if self.closing||self.taken{return Err(invalid("closed history envelope header cannot resume"))}let d=self.demands(document,actor,observed,grant.maximum_copy_bytes)?;if self.ready()||!retained_clone_grant_admits(grant,d){return Ok(Default::default())}self.source=Some(stamp(document,actor,observed));if self.field==1{let (alias,_)=actor.0.admit_clone(grant)?;*self.actor=Some(ActorId(alias));self.field+=1;return Ok(progress(d))}let source=match self.field{0=>Some(document),1=>None,2|3=>Some(HISTORY_TRANSITION_SCHEMA),4=>observed,_=>None};if let Some(source)=source{if let Some(target)=self.text[self.field].as_mut(){if target.len()==source.len(){self.field+=1;}else{let start=target.len();let mut end=(start+64).min(source.len());while !source.is_char_boundary(end){end-=1;}target.push_str(&source[start..end]);}}else{let mut target=String::new();target.try_reserve_exact(source.len()).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"history envelope original header reservation failed"))?;self.text[self.field]=Some(target);}}else{self.field+=1;}Ok(progress(d))}
 /// 🏁️ Readiness implies all actual header strings exist while payload ownership remains separate.
 pub fn ready(&self)->bool{self.field==5&&!self.taken&&!self.closing}
 /// 📏️ The original pages, dependency vector and target vector move together without body copies.
 pub fn take_demands()->RetirementDemand{header::<(MutationEnvelope,Option<(CausalPayload,MutationId)>,Vec<MutationId>,Vec<String>)>()}
 /// 🤝️ Creates the canonical envelope from the same original admitted allocations.
 pub fn take(&mut self,payload:&mut Option<(CausalPayload,MutationId)>,dependencies:&mut Vec<MutationId>,target:&mut Vec<String>,timestamp:HybridLogicalTimestamp,grant:RetainedCloneGrant)->Result<Option<(MutationEnvelope,RetainedCloneProgress)>,ValueError>{if !self.ready(){return Err(invalid("history envelope original headers are not ready"))}if payload.is_none(){return Err(invalid("history envelope original payload is absent"))}let d=Self::take_demands();if !retained_clone_grant_admits(grant,d){return Ok(None)}let (bytes,mutation_id)=payload.take().unwrap();let value=MutationEnvelope{mutation_id,document_id:ArtifactId(self.text[0].take().unwrap()),actor:self.actor.take().unwrap(),dependencies:std::mem::take(dependencies),observed:self.text[4].take().map(MutationId),target:std::mem::take(target),diff:ArtifactDiff{schema:SchemaId(self.text[2].take().unwrap()),payload:bytes},inverse:InverseMutation{schema:SchemaId(self.text[3].take().unwrap()),payload:Default::default()},timestamp,transaction:None,verb:None,line:None};self.taken=true;Ok(Some((value,progress(d))))}
 /// 🛑️ Cancellation preserves every partly copied original string until paid closure.
 pub fn begin_close(&mut self){self.closing=true;}
 /// 📏️ Prices one original string's typed close or the final borrowed-coordinate reset.
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.actor.is_some(){return self.retirement.next_owner_demands::<ActorId>(true,&None,body)}if self.text.iter().any(Option::is_some){return self.retirement.next_owner_demands::<String>(true,&None,body)}Ok(header::<Option<[(usize,usize);3]>>())}
 /// ♻️ Original strings and their actual retirement frames close before the source identity is forgotten.
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.begin_close();if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands(grant.maximum_copy_bytes)?;if !retained_clone_grant_admits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.retirement.is_empty(){return self.retirement.select(grant.maximum_copy_bytes)?.step(grant).map(|step|RetainedCloneStep::Progress(step.progress()))}if self.actor.is_some(){return Ok(self.retirement.begin_granted(&mut self.actor,grant)?.map_or(RetainedCloneStep::Progress(Default::default()),|step|RetainedCloneStep::Progress(step.progress())))}if let Some(slot)=self.text.iter_mut().find(|slot|slot.is_some()){return Ok(self.retirement.begin_granted(slot,grant)?.map_or(RetainedCloneStep::Progress(Default::default()),|step|RetainedCloneStep::Progress(step.progress())))}self.source=None;Ok(RetainedCloneStep::Progress(progress(d)))}
 /// 🫙️ Moved output ownership stays with the recipient; this cursor retains no hidden header or close frame.
 pub fn terminal_is_empty(&self)->bool{self.source.is_none()&&self.actor.is_none()&&self.text.iter().all(Option::is_none)&&self.retirement.is_empty()}
}
impl Drop for OriginalHistoryEnvelopeHeader{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"history envelope headers require funded original closure");}}

